// Each bookmaker back price beside the lowest exchange lay with at least minLayAvailable at that price, rated:
// back / lay x 100, and after your commission c, back x (1 - c) / (lay - c) x 100. The prices carry no commission.
// Pairs rated at or above minRating are added or updated on row_key; the sheet's rows that are no longer among them
// (the event has started, a price has gone, or the rating is under minRating) are removed.
const s = $('Settings').first().json;
const c = Number(s.commissionPercent) / 100;
const round = (x) => Math.round(x * 100) / 100;
// UK time as yyyy-mm-dd hh:mm, which sorts as text ('sv-SE' writes dates in that order)
const ukTime = (t) => new Date(t).toLocaleString('sv-SE', { timeZone: 'Europe/London' }).slice(0, 16);
const checkedAt = ukTime(Date.now());
const keep = [];

for (const ev of $('Read the matched board').first().json.data ?? []) {
  const event = ev.home_team && ev.away_team ? `${ev.home_team} v ${ev.away_team}` : (ev.event_name ?? ev.venue ?? ev.sport_title);
  for (const market of ev.markets ?? []) {
    for (const o of market.outcomes ?? []) {
      const lays = Array.isArray(o.lay) ? o.lay.filter((l) => l.price > 1 && (l.available ?? 0) >= Number(s.minLayAvailable)) : [];
      if (!lays.length) continue;
      const lay = lays.reduce((low, l) => (l.price < low.price ? l : low));
      const outcome = o.point == null ? o.name : `${o.name} ${o.point}`;
      for (const back of o.back ?? []) {
        if (!(back.price > 1)) continue;
        const ratingAfterCommission = round(((back.price * (1 - c)) / (lay.price - c)) * 100);
        if (ratingAfterCommission < Number(s.minRating)) continue;
        keep.push({
          json: {
            row_key: [ev.event_id, market.key, outcome, back.bookmaker].join('|'),
            checked_at: checkedAt,
            kick_off: ev.commence_time ? ukTime(ev.commence_time) : '',
            competition: ev.sport_title,
            event,
            market: market.key,
            outcome,
            bookmaker: back.bookmaker,
            back: back.price,
            exchange: lay.exchange,
            lay: lay.price,
            lay_available: lay.available ?? '',
            rating: round((back.price / lay.price) * 100),
            rating_after_commission: ratingAfterCommission,
            back_link: back.link ?? '',
            lay_link: lay.link ?? '',
          },
        });
      }
    }
  }
}

// The sheet's rows that left the board, bottom first, in runs of neighbouring rows: one delete per run, and a
// delete never moves a row that is still to be deleted
const onBoard = new Set(keep.map((r) => r.json.row_key));
const gone = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.row_key && !onBoard.has(String(r.row_key)) && r.row_number > 1)
  .map((r) => r.row_number)
  .sort((a, b) => b - a);
const remove = [];
for (const n of gone) {
  const run = remove.at(-1)?.json;
  if (run && run.remove_from_row === n + 1) {
    run.remove_from_row = n;
    run.rows_to_remove++;
  } else {
    remove.push({ json: { remove_from_row: n, rows_to_remove: 1 } });
  }
}

return [...remove, ...keep];

// A call that still failed after its three tries: one message with the status, the API's error code and
// request id, and what to do next. n8n keeps the API's reply in the error message as: status - "body".
const j = $input.first().json;
const e = j.error && typeof j.error === 'object' ? j.error : { message: String(j.error ?? '') };
const status = Number(e.status ?? e.httpCode ?? j.details?.httpCode) || 0;
let body = j.details?.body;
if (body === undefined) {
  try {
    body = JSON.parse(JSON.parse(String(e.message).replace(/^\d{3} - /, '')));
  } catch {
    body = {};
  }
}
const api = (body && body.error) || {};
const next =
  {
    401: 'Check the API key in the Header Auth credential.',
    402: 'Your token balance is below this call\'s price: narrow the filters in Settings, or choose a plan at app.oddsrelay.io.',
    403: 'A sport, market or venue in Settings is outside your plan.',
    429: 'Too many calls: run the workflow less often.',
  }[status] ?? (status >= 500 || !status ? 'The next scheduled run tries again.' : 'Check the values in Settings.');
const what = [status || 'no reply', api.code, api.message].filter(Boolean).join(', ');
const id = api.request_id ? `, request id ${api.request_id}` : '';
return [{ json: { message: `The OddsRelay API call failed after three tries (${what}${id}). ${next}` } }];
